"""Safe, best-effort export to the user-supplied workbook; the DB remains authoritative."""
import logging
import os
import threading
from collections import Counter
from copy import copy
from decimal import Decimal, InvalidOperation
from pathlib import Path

from openpyxl import load_workbook

logger = logging.getLogger(__name__)
_workbook_lock = threading.Lock()
# This is deliberately the one user-supplied workbook; no replacement
# workbook is ever generated by the exporter.
WORKBOOK_PATH = Path(r"C:\Users\HP\Downloads\FLIPKART OG\FLIPKART OG\order_reports\Bharat_Mart_Orders_Template.xlsx")
ORDER_HEADERS = ["Order ID", "Order Date", "Order Time", "Customer Name", "Customer Email", "Mobile Number", "Full Delivery Address", "City", "State", "PIN Code", "Order Amount", "Coupon Code", "Coupon Discount", "Payment Method", "Payment Status", "Order Status"]
ITEM_HEADERS = ["Order ID", "Product Name", "Product Category", "Quantity", "Unit Price", "Product Discount", "Final Item Amount"]

def _order_row(order):
    customer = order.customer
    address = order.delivery_address_text or f"{customer.street}, {customer.address}"
    return [order.pk, order.created_at.date(), order.created_at.time().replace(tzinfo=None), customer.full_name, customer.user.email, customer.mobile, address, order.delivery_city or customer.city, order.delivery_state, order.delivery_pin_code or customer.postcode, float(order.total_amount), order.coupon.code if order.coupon else "", float(order.coupon_discount), order.get_payment_method_display(), order.payment_status, order.get_status_display()]


def _item_row(order, item):
    return [order.pk, item.product.name, item.product.category, item.quantity, float(item.price), 0, float(item.subtotal)]


def _value_key(value):
    """Compare Excel values safely across numeric/date conversions by openpyxl."""
    if value is None:
        return ""
    # openpyxl reads an Excel whole-number price as ``2999`` while Django
    # supplies ``2999.0``.  Use one decimal representation for idempotency.
    if isinstance(value, (int, float, Decimal)) and not isinstance(value, bool):
        try:
            return format(Decimal(str(value)).normalize(), "f")
        except (InvalidOperation, ValueError):
            pass
    return str(value).strip()


def _first_empty_data_row(sheet, column_count):
    """Return the first empty record row, even in a pre-formatted template."""
    for row_number in range(2, sheet.max_row + 1):
        if all(sheet.cell(row_number, column).value is None for column in range(1, column_count + 1)):
            return row_number
    return sheet.max_row + 1


def _write_row(sheet, values):
    """Write into the first visual record row instead of appending after styles."""
    row_number = _first_empty_data_row(sheet, len(values))
    # When the template does not already contain a styled blank row, inherit
    # the first data-row formatting instead of creating an unformatted row.
    if row_number > sheet.max_row:
        for column in range(1, len(values) + 1):
            sheet.cell(row_number, column)._style = copy(sheet.cell(2, column)._style)
            sheet.cell(row_number, column).number_format = sheet.cell(2, column).number_format
    for column, value in enumerate(values, start=1):
        sheet.cell(row_number, column).value = value
    return row_number


def _compact_data_rows(sheet, column_count):
    """Move real records above styled blank rows without rebuilding the sheet."""
    source_rows = [
        row_number for row_number in range(2, sheet.max_row + 1)
        if sheet.cell(row_number, 1).value is not None
    ]
    target_rows = list(range(2, 2 + len(source_rows)))
    if source_rows == target_rows:
        return False

    records = []
    for row_number in source_rows:
        records.append([
            (sheet.cell(row_number, column).value, copy(sheet.cell(row_number, column)._style), sheet.cell(row_number, column).number_format)
            for column in range(1, column_count + 1)
        ])
    for target_row, record in zip(target_rows, records):
        for column, (value, style, number_format) in enumerate(record, start=1):
            cell = sheet.cell(target_row, column)
            cell.value = value
            cell._style = style
            cell.number_format = number_format
    for row_number in source_rows:
        if row_number not in target_rows:
            for column in range(1, column_count + 1):
                sheet.cell(row_number, column).value = None
    return True


def _refresh_filter(sheet, column_count):
    last_data_row = max(2, 1 + sum(
        sheet.cell(row_number, 1).value is not None
        for row_number in range(2, sheet.max_row + 1)
    ))
    sheet.auto_filter.ref = f"A1:{sheet.cell(1, column_count).coordinate[:-1]}{last_data_row}"


def export_order(order):
    """Synchronise one committed order without replacing the supplied workbook.

    Each worksheet is reconciled independently: a previous crash after writing
    Orders but before Order Items is repaired on retry, while existing rows are
    never duplicated.
    """
    logger.info("Excel export started for order_id=%s workbook=%s", order.pk, WORKBOOK_PATH.resolve())
    if not WORKBOOK_PATH.exists():
        logger.error("Excel export workbook missing for order_id=%s workbook=%s", order.pk, WORKBOOK_PATH.resolve())
        raise FileNotFoundError(f"Required workbook is missing: {WORKBOOK_PATH}")
    with _workbook_lock:
        logger.info("Opening Excel workbook for order_id=%s", order.pk)
        workbook = load_workbook(WORKBOOK_PATH)
        logger.info("Excel workbook opened for order_id=%s sheets=%s", order.pk, workbook.sheetnames)
        orders, items = workbook["Orders"], workbook["Order Items"]
        if [cell.value for cell in orders[1]][:16] != ORDER_HEADERS or [cell.value for cell in items[1]][:7] != ITEM_HEADERS:
            logger.error("Excel header validation failed for order_id=%s", order.pk)
            raise ValueError("Workbook worksheet names or column headers do not match the supplied template.")
        logger.info("Order data retrieved for order_id=%s", order.pk)
        exported_ids = {_value_key(row[0].value) for row in orders.iter_rows(min_row=2) if row[0].value is not None}
        changed = False
        if _value_key(order.pk) not in exported_ids:
            _write_row(orders, _order_row(order))
            changed = True

        required_item_rows = [
            _item_row(order, item) for item in order.items.select_related("product")
        ]
        logger.info("Order items retrieved for order_id=%s item_count=%s", order.pk, len(required_item_rows))
        required_item_keys = Counter(
            tuple(_value_key(value) for value in row) for row in required_item_rows
        )
        original_rows_by_key = {}
        for row in required_item_rows:
            original_rows_by_key.setdefault(tuple(_value_key(value) for value in row), row)
        existing_item_row_numbers = {}
        for row_number, row in enumerate(items.iter_rows(min_row=2), start=2):
            if row[0].value is not None and _value_key(row[0].value) == _value_key(order.pk):
                row_key = tuple(_value_key(cell.value) for cell in row[:7])
                existing_item_row_numbers.setdefault(row_key, []).append(row_number)
        # A previous interrupted/older exporter may already have created a
        # duplicate. Remove only surplus copies of rows represented in DB.
        duplicate_rows = []
        for row_key, row_numbers in existing_item_row_numbers.items():
            allowed = required_item_keys.get(row_key, 0)
            duplicate_rows.extend(row_numbers[allowed:])
        for row_number in sorted(duplicate_rows, reverse=True):
            items.delete_rows(row_number, 1)
        if duplicate_rows:
            changed = True
            logger.info("Removed surplus duplicate item rows for order_id=%s count=%s", order.pk, len(duplicate_rows))
        existing_item_rows = Counter(
            tuple(_value_key(cell.value) for cell in row[:7])
            for row in items.iter_rows(min_row=2)
            if row[0].value is not None and _value_key(row[0].value) == _value_key(order.pk)
        )
        for row_key, required_count in required_item_keys.items():
            for _ in range(required_count - existing_item_rows[row_key]):
                _write_row(items, original_rows_by_key[row_key])
                changed = True
        if not changed:
            logger.info("Excel export skipped; rows already current for order_id=%s", order.pk)
            return
        _refresh_filter(orders, len(ORDER_HEADERS))
        _refresh_filter(items, len(ITEM_HEADERS))
        temporary = WORKBOOK_PATH.with_suffix(".tmp.xlsx")
        logger.info("Excel rows inserted or updated for order_id=%s; saving workbook=%s", order.pk, WORKBOOK_PATH.resolve())
        workbook.save(temporary)
        os.replace(temporary, WORKBOOK_PATH)
        logger.info("Excel workbook saved and export completed for order_id=%s workbook=%s", order.pk, WORKBOOK_PATH.resolve())

def export_order_after_commit(order_id):
    from .models import Order
    logger.info("Post-commit Excel export callback received order_id=%s", order_id)
    try:
        order = Order.objects.select_related("customer__user", "coupon", "emi_plan").get(pk=order_id)
        export_order(order)
    except Exception:
        logger.exception("Excel export failed for order_id=%s; use reconcile_order_exports to retry.", order_id)

def reconcile_workbook():
    """Export every database order missing from either worksheet, idempotently."""
    from .models import Order
    if not WORKBOOK_PATH.exists():
        raise FileNotFoundError(f"Required workbook is missing: {WORKBOOK_PATH}")
    # The supplied template contains many formatted-but-empty rows. Compact
    # prior append-based exports so records are visible immediately below the
    # headers, then make Excel's filter include the actual data range.
    with _workbook_lock:
        workbook = load_workbook(WORKBOOK_PATH)
        orders_sheet, items_sheet = workbook["Orders"], workbook["Order Items"]
        changed = _compact_data_rows(orders_sheet, len(ORDER_HEADERS))
        changed = _compact_data_rows(items_sheet, len(ITEM_HEADERS)) or changed
        _refresh_filter(orders_sheet, len(ORDER_HEADERS))
        _refresh_filter(items_sheet, len(ITEM_HEADERS))
        if changed:
            temporary = WORKBOOK_PATH.with_suffix(".tmp.xlsx")
            workbook.save(temporary)
            os.replace(temporary, WORKBOOK_PATH)
            logger.info("Compacted existing Excel records into visible rows workbook=%s", WORKBOOK_PATH.resolve())
    for order in Order.objects.select_related("customer__user", "coupon").prefetch_related("items__product").order_by("id"):
        export_order(order)


# Compatibility for any existing admin action/import that used the old name.
regenerate_workbook = reconcile_workbook
